#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> countSubgraphsForEachDiameter(int n, vector<vector<int>>& edges) {
        vector<vector<int>> dist(n, vector<int>(n, 100));
        for (int i = 0; i < n; ++i) dist[i][i] = 0;
        for (const auto& e : edges) {
            int u = e[0] - 1, v = e[1] - 1;
            dist[u][v] = dist[v][u] = 1;
        }
        for (int k = 0; k < n; ++k) {
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
        vector<int> ans(n - 1, 0);
        for (int mask = 1; mask < (1 << n); ++mask) {
            vector<int> nodes;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) nodes.push_back(i);
            }
            if (nodes.size() < 2) continue;
            int e_count = 0;
            for (const auto& e : edges) {
                int u = e[0] - 1, v = e[1] - 1;
                if ((mask & (1 << u)) && (mask & (1 << v))) e_count++;
            }
            if (e_count != (int)nodes.size() - 1) continue;
            int max_d = 0;
            for (size_t i = 0; i < nodes.size(); ++i) {
                for (size_t j = i + 1; j < nodes.size(); ++j) {
                    max_d = max(max_d, dist[nodes[i]][nodes[j]]);
                }
            }
            if (max_d > 0) ans[max_d - 1]++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        int[][] dist = new int[n][n];
        for (int[] row : dist) Arrays.fill(row, 100);
        for (int i = 0; i < n; ++i) dist[i][i] = 0;
        for (int[] e : edges) {
            int u = e[0] - 1, v = e[1] - 1;
            dist[u][v] = dist[v][u] = 1;
        }
        for (int k = 0; k < n; ++k) {
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
        int[] ans = new int[n - 1];
        for (int mask = 1; mask < (1 << n); ++mask) {
            List<Integer> nodes = new ArrayList<>();
            for (int i = 0; i < n; ++i) {
                if ((mask & (1 << i)) != 0) nodes.add(i);
            }
            if (nodes.size() < 2) continue;
            int eCount = 0;
            for (int[] e : edges) {
                int u = e[0] - 1, v = e[1] - 1;
                if ((mask & (1 << u)) != 0 && (mask & (1 << v)) != 0) eCount++;
            }
            if (eCount != nodes.size() - 1) continue;
            int maxD = 0;
            for (int i = 0; i < nodes.size(); ++i) {
                for (int j = i + 1; j < nodes.size(); ++j) {
                    maxD = Math.max(maxD, dist[nodes.get(i)][nodes.get(j)]);
                }
            }
            if (maxD > 0) ans[maxD - 1]++;
        }
        return ans;
    }
}

