var countSubgraphsForEachDiameter = function(n, edges) {
    const dist = Array.from({ length: n }, () => Array(n).fill(100));
    for (let i = 0; i < n; ++i) dist[i][i] = 0;
    for (const [u, v] of edges) {
        dist[u - 1][v - 1] = dist[v - 1][u - 1] = 1;
    }
    for (let k = 0; k < n; ++k) {
        for (let i = 0; i < n; ++i) {
            for (let j = 0; j < n; ++j) {
                dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
    const ans = Array(n - 1).fill(0);
    for (let mask = 1; mask < (1 << n); ++mask) {
        const nodes = [];
        for (let i = 0; i < n; ++i) {
            if (mask & (1 << i)) nodes.push(i);
        }
        if (nodes.length < 2) continue;
        let eCount = 0;
        for (const [u, v] of edges) {
            if ((mask & (1 << (u - 1))) && (mask & (1 << (v - 1)))) eCount++;
        }
        if (eCount !== nodes.length - 1) continue;
        let maxD = 0;
        for (let i = 0; i < nodes.length; ++i) {
            for (let j = i + 1; j < nodes.length; ++j) {
                maxD = Math.max(maxD, dist[nodes[i]][nodes[j]]);
            }
        }
        if (maxD > 0) ans[maxD - 1]++;
    }
    return ans;
};
